from collections import Counter
def blocksig(A):
    d={}
    for r in range(0,12,3):
        for c in range(0,12,3):
            b=A[r:r+3,c:c+3]
            zs=tuple(sorted((int(i),int(j)) for i,j in np.argwhere(b==0)))
            d.setdefault((r//3,c//3),zs)
    return d
